To find the maximum flow in a flow network from a source node to a sink node, you can use the Ford-Fulkerson algorithm. Here's a Python function that implements this algorithm:

```python
from collections import defaultdict

def max_flow(graph, source, sink):
    n = len(graph)
    flow = defaultdict(int)
    level = [0] * n

    def bfs(start):
        queue = [(start, 0)]
        level[start] = 1
        while queue:
            v, level_val = queue.pop(0)
            if v == sink:
                return level_val
            for w, cap in graph[v].items():
                if cap > flow[v][w] and level[w] == 0:
                    level[w] = level_val + 1
                    queue.append((w, level_val + 1))

    while True:
        bfs(source)
        if level[sink] == 0:
            break

        path = [(sink, float('-inf'))]
        for v in range(n)[::-1]:
            if level[v] != level[sink]:
                for w, cap in graph[v].items():
                    if cap > flow[v][w] and level[w] == level[v] + 1:
                        path = [(w, cap - flow[v][w])] + path
                        break
        for v, cap in path[::-1]:
            for w, cap in graph[v].items():
                if cap > flow[v][w]:
                    flow[v][w] += cap
                    flow[w][v] -= cap

    return sum(flow[v][w] for v in flow for w in flow[v])
```

You can use this function to find the maximum flow in the given sample input:

