graph = {'s': {'o': 3, 'p': 3}, 'o': {'q': 3, 'r': 2}, 'p': {'r': 2, 't': 4}, 'q': {'r': 4, 't': 2}, 'r': {'t': 3}, 't': {}}
print(max_flow(graph, 's', 't'))  # Output: 5
